        std::cout << ' ' << x;
    }
    std::cout << '\n';

    const std::vector<std::string> names = {"Ada", "Linus", "Grace"};
    for (const auto& name : names) {
        std::cout << "Hi, " << name << '\n';
    }

    const double prices[3] = {2.5, 4.25, 3.0};
    double total = 0.0;
    for (double p : prices) {
        total += p;
    }
    std::cout << "Total: " << total << '\n';
    return 0;
}

