#include <cstddef>
#include <iostream>
#include <vector>

int main() {
    const std::vector<int> weights = {5, 7, 3, 9, 2};
    const int LIMIT = 15;
    std::size_t i = 0;
    int total = 0;
    while (i < weights.size() && total + weights[i] <= LIMIT) {
        total += weights[i];
        ++i;
    }
    std::cout << i << " items, total " << total << '\n';
    return 0;
}
